function solve(a,b){if(b.length===0){return true;}if(a.length===0||a[0].length===0){return false;}const c=a.length;const d=a[0].length;if(b.length>c*d){return false;}const e=Symbol('visited');function f(g,h,i){if(i===b.length){return true;}if(g<0||g>=c||h<0||h>=d||a[g][h]!==b[i]){return false;}const j=a[g][h];a[g][h]=e;const k=f(g+1,h,i+1)||f(g-1,h,i+1)||f(g,h+1,i+1)||f(g,h-1,i+1);a[g][h]=j;return k;}for(let i=0;i<c;i+=1){for(let j=0;j<d;j+=1){if(f(i,j,0)){return true;}}}return false;}
